import { useState, useEffect } from "react";
import { Container, Row, Col, Card } from "react-bootstrap";
import { useAuth } from "../hooks/useAuth";
import { useDispatch } from "react-redux";
import { logout } from "../app/features/authSlice";
import { useNavigate } from "react-router-dom";
import { ENDPOINTS } from '../app/config/config.js';
import "./profile.css";

const Profile = () => {
  const { user } = useAuth();
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const [userStats, setUserStats] = useState({
    totalReviews: 0,
    averageRating: 0,
    totalPurchases: 0,
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchUserStats();
  }, []);

  const fetchUserStats = async () => {
    try {
      const response = await fetch(`${ENDPOINTS.CommentReview}/getUserStats/${user.username}`);
      if (!response.ok) throw new Error('Failed to fetch user stats');
      const data = await response.json();
      setUserStats(data);
    } catch (error) {
      console.error('Error fetching user stats:', error);
    } finally {
      setLoading(false);
    }
  };

  const getBadges = () => {
    const badges = [];
    
    // Review badges
    if (userStats.totalReviews >= 50) {
      badges.push({ name: "Review Master", icon: "🏆", description: "Posted 50+ reviews" });
    } else if (userStats.totalReviews >= 25) {
      badges.push({ name: "Active Reviewer", icon: "⭐", description: "Posted 25+ reviews" });
    } else if (userStats.totalReviews >= 10) {
      badges.push({ name: "Beginner Reviewer", icon: "📝", description: "Posted 10+ reviews" });
    }

    // Rating badges
    if (userStats.averageRating >= 4.5) {
      badges.push({ name: "Quality Rater", icon: "💎", description: "High-quality ratings" });
    }

    // Purchase badges
    if (userStats.totalPurchases >= 10) {
      badges.push({ name: "Loyal Customer", icon: "🛍️", description: "Made 10+ purchases" });
    }

    return badges;
  };

  const handleLogout = () => {
    dispatch(logout());
    navigate("/");
  };

  if (loading) {
    return <div className="loading-spinner">Loading profile...</div>;
  }

  return (
    <Container className="profile-container">
      <Row>
        {/* User Info Card */}
        <Col md={4}>
          <Card className="profile-card">
            <div className="profile-header">
              <div className="profile-avatar">
                {user.username.charAt(0).toUpperCase()}
              </div>
              <h2>{user.username}</h2>
              <p className="member-since">Member since {new Date(user.createdAt).toLocaleDateString()}</p>
            </div>
            <button onClick={handleLogout} className="logout-btn">
              Logout
            </button>
          </Card>
        </Col>

        {/* Stats Card */}
        <Col md={8}>
          <Card className="stats-card">
            <h3>Your Activity</h3>
            <div className="stats-grid">
              <div className="stat-item">
                <span className="stat-value">{userStats.totalReviews}</span>
                <span className="stat-label">Reviews</span>
              </div>
              <div className="stat-item">
                <span className="stat-value">{userStats.averageRating.toFixed(1)}</span>
                <span className="stat-label">Avg Rating</span>
              </div>
              <div className="stat-item">
                <span className="stat-value">{userStats.totalPurchases}</span>
                <span className="stat-label">Purchases</span>
              </div>
            </div>
          </Card>

          {/* Badges Card */}
          <Card className="badges-card">
            <h3>Your Badges</h3>
            <div className="badges-grid">
              {getBadges().map((badge, index) => (
                <div key={index} className="badge-item">
                  <span className="badge-icon">{badge.icon}</span>
                  <span className="badge-name">{badge.name}</span>
                  <span className="badge-description">{badge.description}</span>
                </div>
              ))}
              {getBadges().length === 0 && (
                <p className="no-badges">Start reviewing products to earn badges!</p>
              )}
            </div>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default Profile;