import { useNavigate } from 'react-router-dom';
import './landing.css';
import useWindowScrollToTop from "../hooks/useWindowScrollToTop";

const Landing = () => {
    const navigate = useNavigate();
    useWindowScrollToTop();
    const handleVersionSelect = (version) => {
        // Store the selected version in localStorage
        localStorage.setItem('appVersion', version);
        navigate('/home');
    };

    return (
        <div className="landing-container">
            <div className="version-selection">
                <h1>Welcome to Multimart</h1>
                <p>Please select your preferred shopping experience:</p>
                
                <div className="buttons-container">
                    <button 
                        className="version-btn gamification"
                        onClick={() => handleVersionSelect('gamification')}
                    >
                        <h2>Gamification Version</h2>
                        <p>Enjoy shopping with:</p>
                        <ul>
                            <li>Special Discounts</li>
                            <li>Rewards System</li>
                            <li>Achievement Badges</li>
                            <li>Interactive Features</li>
                        </ul>
                    </button>

                    <button 
                        className="version-btn simple"
                        onClick={() => handleVersionSelect('simple')}
                    >
                        <h2>Simple Version</h2>
                        <p>Basic shopping with:</p>
                        <ul>
                            <li>Product Listings</li>
                            <li>Shopping Cart</li>
                            <li>Quick Checkout</li>
                            <li>Clean Interface</li>
                        </ul>
                    </button>
                </div>
            </div>
        </div>
    );
};

export default Landing;